PROGRAM ProductionControl
VAR
    // Inputs
    Mode            : BOOL;
    ForwardButton   : BOOL;
    ReverseButton   : BOOL;
    SensorFeed      : BOOL;
    SensorWash      : BOOL;
    SensorWeight    : BOOL;
    SensorFiring    : BOOL;
    SensorOutput    : BOOL;
    washComplete    : BOOL;
    weightComplete  : BOOL;
    weight          : REAL;
    firingComplete  : BOOL;

    // Outputs
    MotorForward    : BOOL;
    MotorReverse    : BOOL;
    kick            : BOOL;
    CompletionLight : BOOL;
    firingTemp      : REAL;

    // Internal variables
    curState        : INT := IDLE;
    lastSensorFeed, lastSensorWash, lastSensorWeight, lastSensorFiring, lastSensorOutput : BOOL := FALSE;
    lastWashComplete, lastWeightComplete, lastFiringComplete : BOOL := FALSE;
    sensorFeedRising, sensorWashRising, sensorWeightRising, sensorFiringRising, sensorOutputRising : BOOL;
    sensorOutputFalling : BOOL;
    washCompleteRising, weightCompleteRising, firingCompleteRising : BOOL;
    // Additional flags for completion signals to avoid repeated triggers
    weightProcessed : BOOL := FALSE;
    washProcessed   : BOOL := FALSE;
    firingProcessed : BOOL := FALSE;
END_VAR

// Edge detection
sensorFeedRising   := SensorFeed AND NOT lastSensorFeed;
sensorWashRising   := SensorWash AND NOT lastSensorWash;
sensorWeightRising := SensorWeight AND NOT lastSensorWeight;
sensorFiringRising := SensorFiring AND NOT lastSensorFiring;
sensorOutputRising := SensorOutput AND NOT lastSensorOutput;
sensorOutputFalling:= NOT SensorOutput AND lastSensorOutput;

washCompleteRising   := washComplete   AND NOT lastWashComplete;
weightCompleteRising := weightComplete AND NOT lastWeightComplete;
firingCompleteRising := firingComplete AND NOT lastFiringComplete;

// Update last values
lastSensorFeed   := SensorFeed;
lastSensorWash   := SensorWash;
lastSensorWeight := SensorWeight;
lastSensorFiring := SensorFiring;
lastSensorOutput := SensorOutput;
lastWashComplete   := washComplete;
lastWeightComplete := weightComplete;
lastFiringComplete := firingComplete;

// Mode handling
IF Mode = FALSE THEN // Manual Mode
    // Reset automatic control outputs
    MotorForward    := FALSE;
    MotorReverse    := FALSE;
    kick            := FALSE;
    CompletionLight := FALSE;
    firingTemp      := 0.0;
    // Reset state machine
    curState        := IDLE;
    weightProcessed := FALSE;
    washProcessed   := FALSE;
    firingProcessed := FALSE;

    // Interlocked forward/reverse control
    IF ForwardButton AND NOT ReverseButton THEN
        MotorForward := TRUE;
    ELSE
        MotorForward := FALSE;
    END_IF
    IF ReverseButton AND NOT ForwardButton THEN
        MotorReverse := TRUE;
    ELSE
        MotorReverse := FALSE;
    END_IF
ELSE // Automatic Mode
    // Ensure manual motor outputs off
    MotorReverse := FALSE;

    // State machine
    CASE curState OF
        IDLE:
            // Wait for material arrival at feed
            IF sensorFeedRising THEN
                curState := MOVING_TO_WASH;
                MotorForward := TRUE;
            ELSE
                MotorForward := FALSE;
                kick := FALSE;
                CompletionLight := FALSE;
                firingTemp := 0.0;
            END_IF

        MOVING_TO_WASH:
            // Move material to cleaning station
            IF sensorWashRising THEN
                // Arrived at wash station
                MotorForward := FALSE;
                curState := AT_WASH;
                washProcessed := FALSE;
            END_IF

        AT_WASH:
            // Waiting for cleaning completion
            IF washCompleteRising AND NOT washProcessed THEN
                MotorForward := TRUE;
                curState := MOVING_TO_WEIGH;
                washProcessed := TRUE;
            END_IF

        MOVING_TO_WEIGH:
            // Move material to weighing station
            IF sensorWeightRising THEN
                MotorForward := FALSE;
                curState := AT_WEIGH;
                weightProcessed := FALSE;
            END_IF

        AT_WEIGH:
            // Waiting for weighing completion
            IF weightCompleteRising AND NOT weightProcessed THEN
                weightProcessed := TRUE;
                // Determine qualification
                IF weight >= 100.0 AND weight <= 200.0 THEN
                    // Qualified: compute firing temperature
                    firingTemp := 500.0 + ((weight - 100.0) / 100.0) * 50.0;
                    // Move to firing
                    MotorForward := TRUE;
                    curState := MOVING_TO_FIRING;
                ELSE
                    // Unqualified: reject
                    kick := TRUE;
                    MotorForward := FALSE;
                    curState := REJECT;
                END_IF
            END_IF

        MOVING_TO_FIRING:
            // Move material to firing station
            IF sensorFiringRising THEN
                MotorForward := FALSE;
                curState := AT_FIRING;
                firingProcessed := FALSE;
            END_IF

        AT_FIRING:
            // Waiting for firing completion
            IF firingCompleteRising AND NOT firingProcessed THEN
                MotorForward := TRUE;
                curState := MOVING_TO_OUTPUT;
                firingProcessed := TRUE;
            END_IF

        MOVING_TO_OUTPUT:
            // Move product to finished product station
            IF sensorOutputRising THEN
                MotorForward := FALSE;
                CompletionLight := TRUE;
                curState := AT_OUTPUT;
            END_IF

        AT_OUTPUT:
            // Product at output; keep light on while sensor present
            CompletionLight := SensorOutput;
            // When product taken away
            IF sensorOutputFalling THEN
                CompletionLight := FALSE;
                // Reset for next product
                curState := IDLE;
                firingTemp := 0.0;
                kick := FALSE;
            END_IF

        REJECT:
            // Unqualified material at weighing station
            kick := TRUE;
            // Keep motor off
            MotorForward := FALSE;
            // When product is removed (assume sensorWeight goes false)
            IF NOT SensorWeight THEN
                kick := FALSE;
                curState := IDLE;
            END_IF

    END_CASE
END_IF

END_PROGRAM

